async function upsertJoinRequest(params) {
  await ensureAoPrecheckTeamTables();
  const id = randomUUID();
  const { rows } = await leaseDialerPool.query(
    `
    INSERT INTO aoprecheck_team_join_requests
      (id, manager_email, manager_name, invited_email, invited_associate_id, invited_name, status, auto_join, last_sent_at, updated_at)
    VALUES ($1,$2,$3,$4,$5,$6,'pending',$7, now(), now())
    ON CONFLICT (lower(manager_email), lower(invited_email)) DO UPDATE SET
      status = 'pending',
      manager_name = COALESCE(EXCLUDED.manager_name, aoprecheck_team_join_requests.manager_name),
      invited_associate_id = COALESCE(EXCLUDED.invited_associate_id, aoprecheck_team_join_requests.invited_associate_id),
      invited_name = COALESCE(EXCLUDED.invited_name, aoprecheck_team_join_requests.invited_name),
      auto_join = EXCLUDED.auto_join,
      resend_count = aoprecheck_team_join_requests.resend_count + 1,
      last_sent_at = now(),
      updated_at = now(),
      responded_at = NULL
    RETURNING *
    `,
    [
      id,
      normEmail(params.managerEmail),
      params.managerName,
      normEmail(params.invitedEmail),
      params.invitedAssociateId,
      params.invitedName,
      !!params.autoJoin
    ]
  );
  return rows[0];
}
async function autoJoinPendingInvites(me) {
  const email = normEmail(me);
  if (!email) return 0;
  await ensureAoPrecheckTeamTables();
  let joined = 0;
  try {
    const { rows } = await leaseDialerPool.query(
      `SELECT * FROM aoprecheck_team_join_requests
         WHERE lower(invited_email)=lower($1) AND status='pending' AND auto_join=true`,
      [email]
    );
    for (const row of rows) {
      let associateId = row.invited_associate_id || "";
      let name = row.invited_name || null;
      if (!associateId) {
        const resolved = await resolveAssociateForEmail(email);
        associateId = resolved?.associateId || "";
        name = name || resolved?.name || null;
      }
      if (!associateId) continue;
      const add = await addCentralMember(row.manager_email, { associateId, agentName: name, agentEmail: email });
      if (add.ok) {
        await leaseDialerPool.query(
          `UPDATE aoprecheck_team_join_requests
             SET status='accepted', responded_at=now(), updated_at=now(),
                 invited_associate_id=COALESCE(invited_associate_id,$2)
           WHERE id=$1`,
          [row.id, associateId]
        );
        joined++;
        console.log(`[aoprecheck][bulk-invite] AUTO-JOINED (bypass approval) invited=${email} manager=${row.manager_email} associate=${associateId}`);
      }
    }
  } catch (e) {
    console.error("[aoprecheck] autoJoinPendingInvites failed:", e instanceof Error ? e.message : String(e));
  }
  return joined;
}
