async function applyConfirmedInvitesForEmail(email) {
  await ensureAoPrecheckTeamTables();
  const inv = await leaseDialerPool.query(
    `SELECT team_id FROM aoprecheck_team_invites WHERE lower(email)=lower($1) AND membership_status='confirmed' AND team_id IS NOT NULL`,
    [email]
  );
  for (const row of inv.rows || []) {
    await leaseDialerPool.query(
      `INSERT INTO aoprecheck_team_members(team_id,email,membership_status,confirmed_at) VALUES ($1,$2,'confirmed',now())
       ON CONFLICT (team_id,email) DO UPDATE SET membership_status='confirmed', confirmed_at=COALESCE(aoprecheck_team_members.confirmed_at, now())`,
      [row.team_id, email]
    );
  }
}
async function findAuthUserId(email) {
  const normalized = normEmail(email);
  for (let page = 1; page <= 40; page++) {
    const { data } = await db2().auth.admin.listUsers({ page, perPage: 200 });
    const u = data?.users?.find((x) => String(x.email || "").toLowerCase() === normalized);
    if (u) return u.id;
    if (!data?.users || data.users.length < 200) break;
  }
  return null;
}
async function ensureAuthUser(email, password) {
  const normalized = normEmail(email);
  const existing = await findAuthUserId(normalized);
  if (existing) {
    await db2().auth.admin.updateUserById(existing, { password, email_confirm: true });
    return existing;
  }
  const { data, error } = await db2().auth.admin.createUser({ email: normalized, password, email_confirm: true });
  if (error) throw new Error(error.message);
  if (!data.user?.id) throw new Error("createUser: no user id");
  return data.user.id;
}
