    billingRouter.get("/missed-call-transactions", async (req, res) => {
      try {
        const { email } = req.query;
        if (!email || typeof email !== "string") {
          return res.status(400).json({ error: "Email parameter is required" });
        }
        const { supabaseAdmin: supabaseAdmin3 } = await Promise.resolve().then(() => (init_supabase(), supabase_exports));
        if (!supabaseAdmin3) {
          return res.status(500).json({ error: "Database connection not available" });
        }
        const { data: missedCallTransactions, error: missedCallError } = await supabaseAdmin3.from("billing_transactions").select("*").eq("transaction_type", "missed_call").eq("agent_email", email).order("transaction_date", { ascending: false });
        if (missedCallError) {
          console.error("\u274C Error fetching missed call transactions:", missedCallError);
          return res.status(500).json({ error: "Failed to fetch transactions" });
        }
        const missedCallIds = missedCallTransactions?.map((t) => t.transaction_id) || [];
        const { data: refunds } = missedCallIds.length > 0 ? await supabaseAdmin3.from("billing_transactions").select("*").eq("transaction_type", "refund").eq("agent_email", email).in("source_id", missedCallIds).order("transaction_date", { ascending: false }) : { data: [] };
        const allTransactions = [
          ...missedCallTransactions || [],
          ...refunds || []
        ].sort((a, b) => new Date(b.transaction_date).getTime() - new Date(a.transaction_date).getTime());
        const transactionsWithNote = allTransactions.map((t) => ({
          ...t,
          reversal_note: t.transaction_type === "missed_call" ? "This charge was incorrectly applied." : void 0
        }));
        res.json({
          success: true,
          transactions: transactionsWithNote
        });
      } catch (error) {
        console.error("\u274C Error in missed-call-transactions endpoint:", error);
        res.status(500).json({ error: error.message || "Failed to fetch missed call transactions" });
      }
    });
