      flat.primaryISaw = body.primaryISaw !== false ? "True" : "False";
      flat.spouseISaw = body.spouseISaw !== false ? "True" : "False";
      flat.primaryCellPhone = s(body.primaryCellPhone) || s(pDetails.cellPhone);
      flat.spouseCellPhone = s(body.spouseCellPhone) || s(sDetails.cellPhone);
      flat.primaryBestTimeToCall = s(body.primaryBestTimeToCall) || s(pDetails.bestTimeToCall);
      flat.spouseBestTimeToCall = s(body.spouseBestTimeToCall) || s(sDetails.bestTimeToCall);
