      const remaining = creditsRow?.credits_remaining ?? creditsRow?.creditsRemaining ?? 0;
      if (remaining >= 0) {
        return res.status(400).json({
          error: "No credit deficit",
          credits_remaining: remaining
        });
      }
      const deficitCredits = Math.ceil(Math.abs(Number(remaining)));
      if (!deficitCredits || deficitCredits > 1e5) {
        return res.status(400).json({ error: "Invalid deficit amount" });
      }
      const amountCents = deficitCredits * 100;
