  app2.get("/api/appointments/lead-search", async (req, res) => {
    try {
      const agentEmail = String(req.query.agentEmail || req.headers["x-user-email"] || "").trim().toLowerCase();
      const query = String(req.query.query || "").trim();
      const limit = Math.max(1, Math.min(25, Number(req.query.limit || 12)));
      const leadSource = String(req.query.leadSource || "sales").trim().toLowerCase() === "recruit" ? "recruit" : "sales";
      if (!agentEmail || !agentEmail.includes("@")) {
        return res.status(400).json({ success: false, error: "agentEmail is required" });
      }
      if (query.length < 2) {
        return res.json({ success: true, results: [] });
      }
      if (leadSource === "recruit") {
        if (!supabaseAdmin) {
          return res.status(503).json({ success: false, error: "Supabase unavailable" });
        }
        const escaped2 = query.replace(/[%_]/g, "");
        const prefix2 = `${escaped2}%`;
        const digits2 = query.replace(/\D/g, "");
        const recruitSearch = digits2.length >= 3 ? `phone.ilike.${digits2}%,first_name.ilike.${prefix2},last_name.ilike.${prefix2}` : `first_name.ilike.${prefix2},last_name.ilike.${prefix2},phone.ilike.${prefix2}`;
        const { data: rows, error } = await supabaseAdmin.from("masterleadrecruit").select("id, first_name, last_name, phone, market, state, city, agent_email, updated_at").or(recruitSearch).or(`agent_email.is.null,agent_email.eq.${agentEmail}`).order("updated_at", { ascending: false }).limit(limit);
        if (error) {
          throw new Error(error.message || "Recruit lead search failed");
        }
        return res.json({
          success: true,
          results: (rows || []).map((lead) => ({
            ...lead,
            lead_id: lead.id,
            name: [lead.first_name, lead.last_name].filter(Boolean).join(" ").trim(),
            source: "recruit"
          }))
        });
      }
      const digits = query.replace(/\D/g, "");
      if (digits.length >= 10) {
        return res.json({ success: true, results: [] });
      }
      const escaped = query.replace(/[%_]/g, "\\$&");
      const prefix = `${escaped}%`;
      const values = [agentEmail, limit];
      let searchClause = `
        (
          lower(first_name) LIKE lower($3) ESCAPE '\\'
          OR lower(last_name) LIKE lower($3) ESCAPE '\\'
          OR taalk_lead_id::text LIKE $3 ESCAPE '\\'
        )
      `;
      values.push(prefix);
      if (digits.length >= 3) {
        searchClause = `
          (
            taalk_lead_id::text LIKE $3 ESCAPE '\\'
          )
        `;
        values.length = 2;
        values[2] = `%${query.replace(/[%_]/g, "\\$&")}%`;
      }
      const result = await pool.query(
        `
          SELECT
            id,
            taalk_lead_id,
            first_name,
            last_name,
            phone,
            COALESCE(taalk_market, market) AS market,
            COALESCE(taalk_state, state) AS state,
            taalk_city AS city,
            cn_email,
            cnresolution,
            updated_at
          FROM masterlead
          WHERE ${searchClause}
            AND (
              COALESCE(btrim(cn_email), '') = ''
              OR lower(btrim(cn_email)) = $1
            )
          ORDER BY
            CASE WHEN lower(btrim(COALESCE(cn_email, ''))) = $1 THEN 0 ELSE 1 END,
            updated_at DESC NULLS LAST,
            id DESC
          LIMIT $2
        `,
        values
      );
      return res.json({
        success: true,
        results: result.rows.map((lead) => ({
          ...lead,
          name: [lead.first_name, lead.last_name].filter(Boolean).join(" ").trim(),
          source: "sales"
        }))
      });
    } catch (error) {
      console.error("\u274C Appointment lead search failed:", error);
      return res.status(500).json({
        success: false,
        error: "Lead search failed",
        details: error instanceof Error ? error.message : String(error)
      });
    }
  });
